def parse(txt):
    import re
    grids={}
    lines=txt.split('\n')
    i=0
    while i<len(lines):
        m=re.match(r'(Demo pair \d+|Test input) (input|output) \((\d+)x(\d+)\):', lines[i])
        if m:
            name,dim1,dim2=m.group(1),int(m.group(3)),int(m.group(4))
            g=[[int(x) for x in lines[i+1+r].split()] for r in range(dim1)]
            grids[(name,'in' if m.group(2)=='input' else 'out')]=g
            i+=1+dim1
        else: i+=1
    return grids
